        [Fact(DisplayName = "seasons > turn every ... days: spring, summer, autumn, winter, and round again")]
        public void T002_turn_every_days_spring_summer_autumn_winter_and_round_again()
        {
            expect(new List<double> { 1, 6, 11, 16, 21 }.map((d) => Seasons.seasonOf(dayStart(d)))).toEqual(Js.Arr(["spring", "summer", "autumn", "winter", "spring"]));
        }

        [Fact(DisplayName = "seasons > crops grow fully in spring, half in autumn, not at all in winter")]
        public void T003_crops_grow_fully_in_spring_half_in_autumn_not_at_all_in_wint()
        {
            expect(growthOver(field(1), 100)).toBe(100);
            expect(growthOver(field(11), 100)).toBe(50);
            expect(growthOver(field(16), 100)).toBe(0);
            expect(Farming.GROW_TICKS).toBeGreaterThan(100);
        }

        [Fact(DisplayName = "seasons > rain makes crops grow half as fast again")]
        public void T004_rain_makes_crops_grow_half_as_fast_again()
        {
            var state = field(2);
            state.weather = "rain";
            expect(Seasons.cropGrows(Js.With(Js.CopyAs<SimState>(state), __s0 => { __s0.tick = 2; }))).toBe(2);
            expect(Seasons.cropGrows(Js.With(Js.CopyAs<SimState>(state), __s1 => { __s1.tick = 3; }))).toBe(1);
