    /// <summary>weather and cold</summary>
    public class D005_weather_and_cold
    {

        [Fact(DisplayName = "weather and cold > is rolled at dawn from day 2, the same for the same seed")]
        public void T006_is_rolled_at_dawn_from_day_2_the_same_for_the_same_seed()
        {
            string roll()
            {
                var state = field(1);
                List<string> @out = [];
                for (var d = 2; d <= 8; d++)
                {
                    state.tick = Js.I(dayStart(d));
                    Tick.tick(state);
                    @out.push(state.weather);
                }
                return @out.join();
            }
            expect(roll()).toBe(roll());
        }

        [Fact(DisplayName = "weather and cold > a winter night outdoors costs health and mood; indoors is warm")]
        public void T007_a_winter_night_outdoors_costs_health_and_mood_indoors_is_war()
        {
            Survivor run(List<string> map)
            {
                var state = ScenarioMod.loadScenario(new Scenario { seed = 2, map = map });
                Js.NN(Js.Get(state.survivors, 0)).priorities = new(JobTypes.NO_JOBS) {  };
                state.tick = Js.I(dayStart(16) + (16 * Time.TICKS_PER_HOUR));
                for (var i = 0; i < 200; i++)
                {
                    Tick.tick(state);
                }
                return Js.NN(Js.Get(state.survivors, 0));
            }
            var outside = run(["s...."]);
            expect(outside.health).toBeLessThan(1000);
            expect(outside.thoughts.map((t) => t.kind)).toContain("cold");
            var inside = run(["####", "#s.#", "#..#", "##D#"]);
            expect(inside.thoughts.map((t) => t.kind)).not.toContain("cold");
